function card(entry) {
  return { title: entry.title.trim(), body: entry.body.trim() };
}

module.exports = { card };
const test = require('node:test');
const assert = require('node:assert');
const { card } = require('../src/card');

test('a card trims its fields', () => {
  assert.deepStrictEqual(card({ title: ' Hi ', body: ' there ' }), { title: 'Hi', body: 'there' });
});
